//! `ConstExprent` against Vineflower 1.12.0 (`data/b02/GenConstOracle.java` ->
//! `data/b02/const_golden.txt`, regenerated by `data/b02/gen.sh`): the
//! uninlining tables in iteration order, and `toJava`/`getPrecedence`/`toString`
//! of every literal form under each option that can change it.
//!
//! A row whose Rust side reaches a body other slices have not ported yet
//! (`UnportedError`: the `FieldExprent` behind a named constant, the cast type
//! name of a class literal) is counted as blocked, not failed.

use std::path::Path;
use std::rc::Rc;

use kuna_jvm::byte_cursor::ByteCursor;
use kuna_jvm::classes_processor::{ClassNode, ClassNodeType};
use kuna_jvm::const_exprent::{ConstExprent, ConstValue};
use kuna_jvm::decompiler_context::DecompilerContext;
use kuna_jvm::i_fernflower_preferences::IFernflowerPreferences;
use kuna_jvm::import_collector::ImportCollector;
use kuna_jvm::rt::Shared;
use kuna_jvm::struct_class::StructClass;
use kuna_jvm::text_buffer::TextBuffer;
use kuna_jvm::text_token_dump_visitor::TextTokenDumpVisitor;
use kuna_jvm::text_token_visitor::TextTokenVisitor;
use kuna_jvm::var_type::VarType;

use crate::common;
use crate::f2_types::{esc, run, same, unesc};

const GOLDEN: &str = include_str!("data/b02/const_golden.txt");
const NO_TOKENS: &str = "\n/*\nTokens:\n*/\n";

fn dump(buf: TextBuffer) -> String {
    let shared = Shared::new(buf);
    let target = shared.clone();
    let mut visitor = <dyn TextTokenVisitor>::create_visitor_with(Rc::new(
        move |next: Box<dyn TextTokenVisitor>| {
            Box::new(TextTokenDumpVisitor::new(next, target.clone())) as Box<dyn TextTokenVisitor>
        },
    ));
    TextBuffer::visit_tokens_shared(&shared, Some(visitor.as_mut()));
    let text = shared.borrow().convert_to_string_and_allow_data_discard();
    match text.strip_suffix(NO_TOKENS) {
        Some(stripped) => stripped.to_string(),
        None => text,
    }
}

fn vartype(name: &str) -> VarType {
    match name {
        "VARTYPE_UNKNOWN" => VarType::VARTYPE_UNKNOWN(),
        "VARTYPE_INT" => VarType::VARTYPE_INT(),
        "VARTYPE_FLOAT" => VarType::VARTYPE_FLOAT(),
        "VARTYPE_LONG" => VarType::VARTYPE_LONG(),
        "VARTYPE_DOUBLE" => VarType::VARTYPE_DOUBLE(),
        "VARTYPE_BYTE" => VarType::VARTYPE_BYTE(),
        "VARTYPE_CHAR" => VarType::VARTYPE_CHAR(),
        "VARTYPE_SHORT" => VarType::VARTYPE_SHORT(),
        "VARTYPE_BOOLEAN" => VarType::VARTYPE_BOOLEAN(),
        "VARTYPE_BYTECHAR" => VarType::VARTYPE_BYTECHAR(),
        "VARTYPE_SHORTCHAR" => VarType::VARTYPE_SHORTCHAR(),
        "VARTYPE_NULL" => VarType::VARTYPE_NULL(),
        "VARTYPE_STRING" => VarType::VARTYPE_STRING(),
        "VARTYPE_CLASS" => VarType::VARTYPE_CLASS(),
        "VARTYPE_OBJECT" => VarType::VARTYPE_OBJECT(),
        "VARTYPE_INTEGER" => VarType::VARTYPE_INTEGER(),
        "VARTYPE_CHARACTER" => VarType::VARTYPE_CHARACTER(),
        "VARTYPE_BYTE_OBJ" => VarType::VARTYPE_BYTE_OBJ(),
        "VARTYPE_SHORT_OBJ" => VarType::VARTYPE_SHORT_OBJ(),
        "VARTYPE_BOOLEAN_OBJ" => VarType::VARTYPE_BOOLEAN_OBJ(),
        "VARTYPE_FLOAT_OBJ" => VarType::VARTYPE_FLOAT_OBJ(),
        "VARTYPE_DOUBLE_OBJ" => VarType::VARTYPE_DOUBLE_OBJ(),
        "VARTYPE_LONG_OBJ" => VarType::VARTYPE_LONG_OBJ(),
        "VARTYPE_METHODTYPE" => VarType::VARTYPE_METHODTYPE(),
        other => panic!("unknown type {other}"),
    }
}

fn value(spec: &str) -> Option<ConstValue> {
    if spec == "N" {
        return None;
    }
    let v = &spec[2..];
    Some(match &spec[..1] {
        "I" => ConstValue::Int(v.parse().unwrap()),
        "J" => ConstValue::Long(v.parse().unwrap()),
        "F" => ConstValue::Float(f32::from_bits(u32::from_str_radix(v, 16).unwrap())),
        "D" => ConstValue::Double(f64::from_bits(u64::from_str_radix(v, 16).unwrap())),
        "S" => ConstValue::String(v.to_string()),
        other => panic!("bad value spec {other}"),
    })
}

fn bits_of(v: &ConstValue) -> String {
    match v {
        ConstValue::Double(d) => format!("D:{:x}", d.to_bits()),
        ConstValue::Float(f) => format!("F:{:x}", f.to_bits()),
        other => panic!("not a floating key {other:?}"),
    }
}

fn golden(tag: &str) -> Vec<Vec<&'static str>> {
    GOLDEN
        .lines()
        .map(|l| l.split('\t').collect::<Vec<_>>())
        .filter(|f| f[0] == tag)
        .collect()
}

#[test]
fn uninlining_tables_match_vineflower() {
    let doubles: Vec<String> = ConstExprent::UNINLINED_DOUBLES()
        .key_vec()
        .iter()
        .map(|k| bits_of(k)[2..].to_string())
        .collect();
    let java_doubles: Vec<String> = golden("KD").iter().map(|f| f[2].to_string()).collect();
    assert_eq!(doubles, java_doubles, "UNINLINED_DOUBLES iteration order");

    let floats: Vec<String> = ConstExprent::UNINLINED_FLOATS()
        .key_vec()
        .iter()
        .map(|k| bits_of(k)[2..].to_string())
        .collect();
    let java_floats: Vec<String> = golden("KF").iter().map(|f| f[2].to_string()).collect();
    assert_eq!(floats, java_floats, "UNINLINED_FLOATS iteration order");

    let mut no_paren: Vec<String> = ConstExprent::NO_PAREN_VALUES()
        .to_vec()
        .iter()
        .map(bits_of)
        .collect();
    no_paren.sort();
    let java_no_paren: Vec<String> = golden("NP").iter().map(|f| f[1].to_string()).collect();
    assert_eq!(no_paren, java_no_paren, "NO_PAREN_VALUES");
}

struct Rows {
    checked: usize,
    blocked: usize,
    failures: Vec<String>,
}

impl Rows {
    fn check(&mut self, what: &str, java: &str, rust: String) {
        if rust.starts_with("EXC:UnportedError:") {
            self.blocked += 1;
            return;
        }
        self.checked += 1;
        if !same(java, &rust) {
            self.failures
                .push(format!("{what}\n   java: {java}\n   rust: {rust}"));
        }
    }
}

fn make(ctor: &str, type_name: &str, spec: &str, condy: bool) -> ConstExprent {
    let val = value(spec);
    if ctor == "T" {
        if condy {
            ConstExprent::new_condy(vartype(type_name), val, None, true)
        } else {
            ConstExprent::new(vartype(type_name), val, None)
        }
    } else {
        let int = val.expect("int value").as_int();
        ConstExprent::new_int(int, ctor == "G1", None)
    }
}

#[test]
fn const_to_java_matches_vineflower() {
    let _guard = common::install_default_context();
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/f6/tree/pkg/Hello.class");
    let bytes = std::fs::read(path).expect("Hello.class");
    let cl = StructClass::create(&mut ByteCursor::new(bytes), true);
    let node = ClassNode::new(ClassNodeType::Root, cl);
    DecompilerContext::set_current_class_node(Some(node));
    DecompilerContext::set_current_class(Some(cl));
    let fresh = || DecompilerContext::start_class(ImportCollector::new(node));

    let mut rows = Rows {
        checked: 0,
        blocked: 0,
        failures: Vec::new(),
    };
    for line in GOLDEN.lines() {
        let f: Vec<&str> = line.split('\t').collect();
        if f[0] != "R" && f[0] != "TS" {
            continue;
        }
        let (ctor, type_name, opts) = (f[1], f[2], f[4]);
        let spec = unesc(f[3]).expect("value spec");
        let flag = |i: usize| opts[i..i + 1].to_string();
        DecompilerContext::set_property(IFernflowerPreferences::LITERALS_AS_IS, flag(0));
        DecompilerContext::set_property(IFernflowerPreferences::ASCII_STRING_CHARACTERS, flag(1));
        DecompilerContext::set_property(IFernflowerPreferences::DECOMPILER_COMMENTS, flag(2));
        let condy = &opts[3..4] == "1";
        let what: String = line.chars().take(100).collect();

        fresh();
        let mut made = None;
        let construction = run(|| {
            made = Some(make(ctor, type_name, &spec, condy));
            String::new()
        });
        if !construction.is_empty() {
            rows.check(&what, f[5], construction);
            continue;
        }
        let c = made.expect("constructed");

        if f[0] == "TS" {
            rows.check(&what, f[5], run(|| esc(Some(&c.to_string()))));
            continue;
        }
        rows.check(&what, f[5], run(|| esc(Some(&dump(c.to_java(0))))));
        fresh();
        rows.check(&what, f[6], run(|| c.get_precedence().to_string()));
    }

    eprintln!(
        "ConstExprent rows: {} checked, {} blocked on unported bodies",
        rows.checked, rows.blocked
    );
    assert!(rows.checked > 10_000, "only {} rows checked", rows.checked);
    assert!(
        rows.failures.is_empty(),
        "{} mismatches:\n{}",
        rows.failures.len(),
        rows.failures
            .iter()
            .take(40)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}
